        source: '<!-- should generate diagnostics -->\n\n<button></button>\n\n<button>   </button>\n\n<menuitem></menuitem>\n\n<!-- `aria-hidden="false"` is still exposed — a label is still required. -->\n<button aria-hidden="false"></button>\n\n<!-- An empty or whitespace-only labeling attribute is not a real label. -->\n<button aria-label=""></button>\n<button aria-label="   "></button>\n<button aria-labelledby=""></button>\n<button title=""></button>\n\n<!-- A valueless or empty `aria-hidden` leaves the control exposed. -->\n<button aria-hidden></button>\n<button aria-hidden=""></button>\n\n<!-- A child with only whitespace supplies no accessible name. -->\n<button><span>   </span></button>\n\n<!-- A comment supplies no accessible name. -->\n<button><!-- save --></button>\n\n<!-- A hidden child does not supply an accessible label. -->\n<button><span aria-hidden="true">Delete</span></button>\n\n<!-- Element names are matched case-insensitively in `.html` files. -->\n<BUTTON></BUTTON>\n\n<!-- PascalCase has no component semantics in `.html` files. -->\n<button><Icon /></button>\n<button><Icon></Icon></button>\n\n<!-- A decorative image supplies no accessible name. -->\n<button><img src="close.png" alt="" /></button>\n\n<!-- Void elements supply no accessible name. -->\n<button><br /></button>\n\n<!-- A hidden input supplies no accessible name. -->\n<button><input type="hidden" /></button>\n',
